function fakeFetch(url) {
  const routes = { "/api/users/1": { status: 200, body: { id: 1, name: "Ada" } } };
  const route = routes[url] || { status: 404, body: { error: "not found" } };
  return new Promise(resolve => setTimeout(() => resolve({
    ok: route.status >= 200 && route.status < 300,
    status: route.status,
    json: () => Promise.resolve(route.body),
  }), 10));
}

async function loadUser(id) {
  const res = await fakeFetch(`/api/users/${id}`);
  const data = await res.json();
  return data.name;
}

loadUser(1).then(name => console.log(name));
loadUser(2).then(name => console.log(name));

